INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'இயக்க முறைமையின் முக்கிய நோக்கம் என்ன?','வன்பொருள் வளங்களை நிர்வகித்தல்','கோப்புகளை மட்டும் உருவாக்குதல்','இணையதளங்களை மட்டும் இயக்குதல்','படங்களை மட்டும் சேமித்தல்','வன்பொருள் வளங்களை நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'ஒரு செயல்முறை என்றால் என்ன?','இயக்கத்தில் உள்ள நிரல்','நிறுத்தப்பட்ட கோப்பு','வன்பொருள் சாதனம்','நெட்வொர்க் கேபிள்','இயக்கத்தில் உள்ள நிரல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'CPU திட்டமிடலின் நோக்கம் என்ன?','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கோப்புகளை அழித்தல்','நினைவகத்தை நிரந்தரமாக நிறுத்துதல்','இணைய வேகத்தை மட்டும் அதிகரித்தல்','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'டெட்லாக் என்றால் என்ன?','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','CPU அதிக வேகத்தில் இயங்கும் நிலை','கோப்பு நகலெடுக்கும் நிலை','நெட்வொர்க் இணைப்பு நிலை','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'மெய்நிகர் நினைவகம் எதற்கு பயன்படுகிறது?','பெரிய நினைவக இடத்தை மாயமாக வழங்க','CPU அளவை அதிகரிக்க','கோப்புகளை மட்டும் சுருக்க','விசைப்பலகையை நிர்வகிக்க','பெரிய நினைவக இடத்தை மாயமாக வழங்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பக்கமிடுதலில் நினைவகம் எவ்வாறு பிரிக்கப்படுகிறது?','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','ஒரே பெரிய பகுதியாக','கோப்புகளாக மட்டும்','த்ரெட்களாக மட்டும்','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'த்ரெட் என்றால் என்ன?','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','வட்டு பகுதி','நினைவக அட்டை','நெட்வொர்க் முகவரி','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'செயல்முறை ஒத்திசைவு ஏன் தேவை?','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','CPU-வை அணைக்க','கோப்புகளை அழிக்க','வலையமைப்பை துண்டிக்க','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'கோப்பு முறைமையின் பணி என்ன?','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','CPU திட்டமிடுதல்','IP முகவரி ஒதுக்குதல்','கேபிள் இணைத்தல்','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'வட்டு திட்டமிடல் எதை மேம்படுத்த முயல்கிறது?','வட்டு அணுகல் செயல்திறனை','CPU வெப்பநிலையை','திரை பிரகாசத்தை','கடவுச்சொல் நீளத்தை','வட்டு அணுகல் செயல்திறனை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'கோப்பு முறைமை தொடர்பாக, இயக்க முறைமையின் முக்கிய நோக்கம் என்ன? (உதாரணம் 11)','வன்பொருள் வளங்களை நிர்வகித்தல்','கோப்புகளை மட்டும் உருவாக்குதல்','இணையதளங்களை மட்டும் இயக்குதல்','படங்களை மட்டும் சேமித்தல்','வன்பொருள் வளங்களை நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'வட்டு திட்டமிடல் தொடர்பாக, ஒரு செயல்முறை என்றால் என்ன? (உதாரணம் 12)','இயக்கத்தில் உள்ள நிரல்','நிறுத்தப்பட்ட கோப்பு','வன்பொருள் சாதனம்','நெட்வொர்க் கேபிள்','இயக்கத்தில் உள்ள நிரல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'உள்ளீடு/வெளியீடு தொடர்பாக, cPU திட்டமிடலின் நோக்கம் என்ன? (உதாரணம் 13)','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கோப்புகளை அழித்தல்','நினைவகத்தை நிரந்தரமாக நிறுத்துதல்','இணைய வேகத்தை மட்டும் அதிகரித்தல்','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பாதுகாப்பு தொடர்பாக, டெட்லாக் என்றால் என்ன? (உதாரணம் 14)','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','CPU அதிக வேகத்தில் இயங்கும் நிலை','கோப்பு நகலெடுக்கும் நிலை','நெட்வொர்க் இணைப்பு நிலை','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'மெய்நிகராக்கம் தொடர்பாக, மெய்நிகர் நினைவகம் எதற்கு பயன்படுகிறது? (உதாரணம் 15)','பெரிய நினைவக இடத்தை மாயமாக வழங்க','CPU அளவை அதிகரிக்க','கோப்புகளை மட்டும் சுருக்க','விசைப்பலகையை நிர்வகிக்க','பெரிய நினைவக இடத்தை மாயமாக வழங்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'இயக்க முறைமையின் அடிப்படைகள் தொடர்பாக, பக்கமிடுதலில் நினைவகம் எவ்வாறு பிரிக்கப்படுகிறது? (உதாரணம் 16)','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','ஒரே பெரிய பகுதியாக','கோப்புகளாக மட்டும்','த்ரெட்களாக மட்டும்','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'செயல்முறைகள் தொடர்பாக, த்ரெட் என்றால் என்ன? (உதாரணம் 17)','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','வட்டு பகுதி','நினைவக அட்டை','நெட்வொர்க் முகவரி','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'த்ரெட்கள் தொடர்பாக, செயல்முறை ஒத்திசைவு ஏன் தேவை? (உதாரணம் 18)','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','CPU-வை அணைக்க','கோப்புகளை அழிக்க','வலையமைப்பை துண்டிக்க','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'CPU திட்டமிடல் தொடர்பாக, கோப்பு முறைமையின் பணி என்ன? (உதாரணம் 19)','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','CPU திட்டமிடுதல்','IP முகவரி ஒதுக்குதல்','கேபிள் இணைத்தல்','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'செயல்முறை ஒத்திசைவு தொடர்பாக, வட்டு திட்டமிடல் எதை மேம்படுத்த முயல்கிறது? (உதாரணம் 20)','வட்டு அணுகல் செயல்திறனை','CPU வெப்பநிலையை','திரை பிரகாசத்தை','கடவுச்சொல் நீளத்தை','வட்டு அணுகல் செயல்திறனை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'டெட்லாக் தொடர்பாக, இயக்க முறைமையின் முக்கிய நோக்கம் என்ன? (உதாரணம் 21)','வன்பொருள் வளங்களை நிர்வகித்தல்','கோப்புகளை மட்டும் உருவாக்குதல்','இணையதளங்களை மட்டும் இயக்குதல்','படங்களை மட்டும் சேமித்தல்','வன்பொருள் வளங்களை நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'நினைவக மேலாண்மை தொடர்பாக, ஒரு செயல்முறை என்றால் என்ன? (உதாரணம் 22)','இயக்கத்தில் உள்ள நிரல்','நிறுத்தப்பட்ட கோப்பு','வன்பொருள் சாதனம்','நெட்வொர்க் கேபிள்','இயக்கத்தில் உள்ள நிரல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'மெய்நிகர் நினைவகம் தொடர்பாக, cPU திட்டமிடலின் நோக்கம் என்ன? (உதாரணம் 23)','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கோப்புகளை அழித்தல்','நினைவகத்தை நிரந்தரமாக நிறுத்துதல்','இணைய வேகத்தை மட்டும் அதிகரித்தல்','CPU பயன்பாட்டை திறம்பட நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பக்கமிடுதல் தொடர்பாக, டெட்லாக் என்றால் என்ன? (உதாரணம் 24)','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','CPU அதிக வேகத்தில் இயங்கும் நிலை','கோப்பு நகலெடுக்கும் நிலை','நெட்வொர்க் இணைப்பு நிலை','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பிரிவு முறை தொடர்பாக, மெய்நிகர் நினைவகம் எதற்கு பயன்படுகிறது? (உதாரணம் 25)','பெரிய நினைவக இடத்தை மாயமாக வழங்க','CPU அளவை அதிகரிக்க','கோப்புகளை மட்டும் சுருக்க','விசைப்பலகையை நிர்வகிக்க','பெரிய நினைவக இடத்தை மாயமாக வழங்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'கோப்பு முறைமை தொடர்பாக, பக்கமிடுதலில் நினைவகம் எவ்வாறு பிரிக்கப்படுகிறது? (உதாரணம் 26)','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','ஒரே பெரிய பகுதியாக','கோப்புகளாக மட்டும்','த்ரெட்களாக மட்டும்','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'வட்டு திட்டமிடல் தொடர்பாக, த்ரெட் என்றால் என்ன? (உதாரணம் 27)','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','வட்டு பகுதி','நினைவக அட்டை','நெட்வொர்க் முகவரி','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'உள்ளீடு/வெளியீடு தொடர்பாக, செயல்முறை ஒத்திசைவு ஏன் தேவை? (உதாரணம் 28)','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','CPU-வை அணைக்க','கோப்புகளை அழிக்க','வலையமைப்பை துண்டிக்க','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பாதுகாப்பு தொடர்பாக, கோப்பு முறைமையின் பணி என்ன? (உதாரணம் 29)','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','CPU திட்டமிடுதல்','IP முகவரி ஒதுக்குதல்','கேபிள் இணைத்தல்','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'மெய்நிகராக்கம் தொடர்பாக, வட்டு திட்டமிடல் எதை மேம்படுத்த முயல்கிறது? (உதாரணம் 30)','வட்டு அணுகல் செயல்திறனை','CPU வெப்பநிலையை','திரை பிரகாசத்தை','கடவுச்சொல் நீளத்தை','வட்டு அணுகல் செயல்திறனை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
