INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'செயல்முறைகள் தொடர்பாக, ஒரு செயல்முறை என்றால் என்ன? (உதாரணம் 32)','இயக்கத்தில் உள்ள நிரல்','நிறுத்தப்பட்ட கோப்பு','வன்பொருள் சாதனம்','நெட்வொர்க் கேபிள்','இயக்கத்தில் உள்ள நிரல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
