INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'CPU திட்டமிடல் தொடர்பாக, டெட்லாக் என்றால் என்ன? (உதாரணம் 34)','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','CPU அதிக வேகத்தில் இயங்கும் நிலை','கோப்பு நகலெடுக்கும் நிலை','நெட்வொர்க் இணைப்பு நிலை','செயல்முறைகள் ஒன்றையொன்று காத்திருக்கும் நிலை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'செயல்முறை ஒத்திசைவு தொடர்பாக, மெய்நிகர் நினைவகம் எதற்கு பயன்படுகிறது? (உதாரணம் 35)','பெரிய நினைவக இடத்தை மாயமாக வழங்க','CPU அளவை அதிகரிக்க','கோப்புகளை மட்டும் சுருக்க','விசைப்பலகையை நிர்வகிக்க','பெரிய நினைவக இடத்தை மாயமாக வழங்க','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'டெட்லாக் தொடர்பாக, பக்கமிடுதலில் நினைவகம் எவ்வாறு பிரிக்கப்படுகிறது? (உதாரணம் 36)','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','ஒரே பெரிய பகுதியாக','கோப்புகளாக மட்டும்','த்ரெட்களாக மட்டும்','நிலையான அளவிலான பக்கங்கள் மற்றும் சட்டகங்களாக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'நினைவக மேலாண்மை தொடர்பாக, த்ரெட் என்றால் என்ன? (உதாரணம் 37)','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','வட்டு பகுதி','நினைவக அட்டை','நெட்வொர்க் முகவரி','செயல்முறைக்குள் இயங்கும் சிறிய செயலாக்க அலகு','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'மெய்நிகர் நினைவகம் தொடர்பாக, செயல்முறை ஒத்திசைவு ஏன் தேவை? (உதாரணம் 38)','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','CPU-வை அணைக்க','கோப்புகளை அழிக்க','வலையமைப்பை துண்டிக்க','பகிரப்பட்ட வளங்களுக்கான பாதுகாப்பான அணுகலுக்காக','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பக்கமிடுதல் தொடர்பாக, கோப்பு முறைமையின் பணி என்ன? (உதாரணம் 39)','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','CPU திட்டமிடுதல்','IP முகவரி ஒதுக்குதல்','கேபிள் இணைத்தல்','கோப்புகளை ஒழுங்கமைத்து நிர்வகித்தல்','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Single Choice','Medium',1,'பிரிவு முறை தொடர்பாக, வட்டு திட்டமிடல் எதை மேம்படுத்த முயல்கிறது? (உதாரணம் 40)','வட்டு அணுகல் செயல்திறனை','CPU வெப்பநிலையை','திரை பிரகாசத்தை','கடவுச்சொல் நீளத்தை','வட்டு அணுகல் செயல்திறனை','கொடுக்கப்பட்ட விருப்பங்களில் சரியான கருத்து இதுவாகும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'இயக்க முறைமையின் முக்கிய பணிகள் எவை?','செயல்முறை மேலாண்மை','நினைவக மேலாண்மை','கோப்பு மேலாண்மை','வள மேலாண்மை','செயல்முறை மேலாண்மை; நினைவக மேலாண்மை; கோப்பு மேலாண்மை; வள மேலாண்மை','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'CPU திட்டமிடல் தொடர்பான கருத்துகள் எவை?','FCFS','SJF','Round Robin','Priority Scheduling','FCFS; SJF; Round Robin; Priority Scheduling','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'டெட்லாக் ஏற்பட காரணமாகும் நிபந்தனைகள் எவை?','பரஸ்பர விலக்கு','வளத்தை பிடித்து காத்திருத்தல்','வலுக்கட்டாய பறிமுதல் இல்லாமை','சுழற்சி காத்திருத்தல்','பரஸ்பர விலக்கு; வளத்தை பிடித்து காத்திருத்தல்; வலுக்கட்டாய பறிமுதல் இல்லாமை; சுழற்சி காத்திருத்தல்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'நினைவக மேலாண்மையில் பயன்படுத்தப்படும் முறைகள் எவை?','பக்கமிடுதல்','பிரிவு முறை','மெய்நிகர் நினைவகம்','ஸ்வாப்பிங்','பக்கமிடுதல்; பிரிவு முறை; மெய்நிகர் நினைவகம்; ஸ்வாப்பிங்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'கோப்பு முறைமை வழங்கும் வசதிகள் எவை?','கோப்பு உருவாக்கம்','கோப்பு நீக்கம்','கோப்பு வாசிப்பு','கோப்பு ஒழுங்கமைப்பு','கோப்பு உருவாக்கம்; கோப்பு நீக்கம்; கோப்பு வாசிப்பு; கோப்பு ஒழுங்கமைப்பு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'இயக்க முறைமையின் முக்கிய பணிகள் எவை? — பயன்பாட்டு நிலை 6','செயல்முறை மேலாண்மை','நினைவக மேலாண்மை','கோப்பு மேலாண்மை','வள மேலாண்மை','செயல்முறை மேலாண்மை; நினைவக மேலாண்மை; கோப்பு மேலாண்மை; வள மேலாண்மை','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'CPU திட்டமிடல் தொடர்பான கருத்துகள் எவை? — பயன்பாட்டு நிலை 7','FCFS','SJF','Round Robin','Priority Scheduling','FCFS; SJF; Round Robin; Priority Scheduling','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'டெட்லாக் ஏற்பட காரணமாகும் நிபந்தனைகள் எவை? — பயன்பாட்டு நிலை 8','பரஸ்பர விலக்கு','வளத்தை பிடித்து காத்திருத்தல்','வலுக்கட்டாய பறிமுதல் இல்லாமை','சுழற்சி காத்திருத்தல்','பரஸ்பர விலக்கு; வளத்தை பிடித்து காத்திருத்தல்; வலுக்கட்டாய பறிமுதல் இல்லாமை; சுழற்சி காத்திருத்தல்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'நினைவக மேலாண்மையில் பயன்படுத்தப்படும் முறைகள் எவை? — பயன்பாட்டு நிலை 9','பக்கமிடுதல்','பிரிவு முறை','மெய்நிகர் நினைவகம்','ஸ்வாப்பிங்','பக்கமிடுதல்; பிரிவு முறை; மெய்நிகர் நினைவகம்; ஸ்வாப்பிங்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'கோப்பு முறைமை வழங்கும் வசதிகள் எவை? — பயன்பாட்டு நிலை 10','கோப்பு உருவாக்கம்','கோப்பு நீக்கம்','கோப்பு வாசிப்பு','கோப்பு ஒழுங்கமைப்பு','கோப்பு உருவாக்கம்; கோப்பு நீக்கம்; கோப்பு வாசிப்பு; கோப்பு ஒழுங்கமைப்பு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'இயக்க முறைமையின் முக்கிய பணிகள் எவை? — பயன்பாட்டு நிலை 11','செயல்முறை மேலாண்மை','நினைவக மேலாண்மை','கோப்பு மேலாண்மை','வள மேலாண்மை','செயல்முறை மேலாண்மை; நினைவக மேலாண்மை; கோப்பு மேலாண்மை; வள மேலாண்மை','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'CPU திட்டமிடல் தொடர்பான கருத்துகள் எவை? — பயன்பாட்டு நிலை 12','FCFS','SJF','Round Robin','Priority Scheduling','FCFS; SJF; Round Robin; Priority Scheduling','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'டெட்லாக் ஏற்பட காரணமாகும் நிபந்தனைகள் எவை? — பயன்பாட்டு நிலை 13','பரஸ்பர விலக்கு','வளத்தை பிடித்து காத்திருத்தல்','வலுக்கட்டாய பறிமுதல் இல்லாமை','சுழற்சி காத்திருத்தல்','பரஸ்பர விலக்கு; வளத்தை பிடித்து காத்திருத்தல்; வலுக்கட்டாய பறிமுதல் இல்லாமை; சுழற்சி காத்திருத்தல்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'நினைவக மேலாண்மையில் பயன்படுத்தப்படும் முறைகள் எவை? — பயன்பாட்டு நிலை 14','பக்கமிடுதல்','பிரிவு முறை','மெய்நிகர் நினைவகம்','ஸ்வாப்பிங்','பக்கமிடுதல்; பிரிவு முறை; மெய்நிகர் நினைவகம்; ஸ்வாப்பிங்','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
