INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'கோப்பு முறைமை வழங்கும் வசதிகள் எவை? — பயன்பாட்டு நிலை 30','கோப்பு உருவாக்கம்','கோப்பு நீக்கம்','கோப்பு வாசிப்பு','கோப்பு ஒழுங்கமைப்பு','கோப்பு உருவாக்கம்; கோப்பு நீக்கம்; கோப்பு வாசிப்பு; கோப்பு ஒழுங்கமைப்பு','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'இயக்க முறைமையின் முக்கிய பணிகள் எவை? — பயன்பாட்டு நிலை 31','செயல்முறை மேலாண்மை','நினைவக மேலாண்மை','கோப்பு மேலாண்மை','வள மேலாண்மை','செயல்முறை மேலாண்மை; நினைவக மேலாண்மை; கோப்பு மேலாண்மை; வள மேலாண்மை','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Multiple Choice','Hard',2,'CPU திட்டமிடல் தொடர்பான கருத்துகள் எவை? — பயன்பாட்டு நிலை 32','FCFS','SJF','Round Robin','Priority Scheduling','FCFS; SJF; Round Robin; Priority Scheduling','கொடுக்கப்பட்டவை அனைத்தும் தொடர்புடைய சரியான கருத்துகள்.');
