INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'இயக்க முறைமை என்றால் என்ன?','','','','','கணினியின் வன்பொருள் மற்றும் மென்பொருள் வளங்களை நிர்வகித்து பயன்பாடுகளுக்கு சேவைகளை வழங்கும் அமைப்பு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'செயல்முறை என்றால் என்ன?','','','','','இயக்கத்தில் உள்ள நிரல் செயல்முறை எனப்படுகிறது.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'த்ரெட் என்றால் என்ன?','','','','','ஒரு செயல்முறைக்குள் செயல்படும் சிறிய செயலாக்க அலகு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'டெட்லாக் என்றால் என்ன?','','','','','பல செயல்முறைகள் தங்களிடம் உள்ள வளங்களை வைத்துக்கொண்டு மற்ற வளங்களுக்காக ஒன்றையொன்று காத்திருக்கும் நிலை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'மெய்நிகர் நினைவகம் என்றால் என்ன?','','','','','முதன்மை நினைவகம் குறைவாக இருக்கும் போது வட்டு இடத்தைப் பயன்படுத்தி பெரிய நினைவக இடம் இருப்பது போல செயல்படும் நுட்பம்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'இயக்க முறைமை என்றால் என்ன? (விரிவாக்கக் கேள்வி 6)','','','','','கணினியின் வன்பொருள் மற்றும் மென்பொருள் வளங்களை நிர்வகித்து பயன்பாடுகளுக்கு சேவைகளை வழங்கும் அமைப்பு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'செயல்முறை என்றால் என்ன? (விரிவாக்கக் கேள்வி 7)','','','','','இயக்கத்தில் உள்ள நிரல் செயல்முறை எனப்படுகிறது.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'த்ரெட் என்றால் என்ன? (விரிவாக்கக் கேள்வி 8)','','','','','ஒரு செயல்முறைக்குள் செயல்படும் சிறிய செயலாக்க அலகு.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'டெட்லாக் என்றால் என்ன? (விரிவாக்கக் கேள்வி 9)','','','','','பல செயல்முறைகள் தங்களிடம் உள்ள வளங்களை வைத்துக்கொண்டு மற்ற வளங்களுக்காக ஒன்றையொன்று காத்திருக்கும் நிலை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'மெய்நிகர் நினைவகம் என்றால் என்ன? (விரிவாக்கக் கேள்வி 10)','','','','','முதன்மை நினைவகம் குறைவாக இருக்கும் போது வட்டு இடத்தைப் பயன்படுத்தி பெரிய நினைவக இடம் இருப்பது போல செயல்படும் நுட்பம்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
