INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'டெட்லாக் என்றால் என்ன? (விரிவாக்கக் கேள்வி 29)','','','','','பல செயல்முறைகள் தங்களிடம் உள்ள வளங்களை வைத்துக்கொண்டு மற்ற வளங்களுக்காக ஒன்றையொன்று காத்திருக்கும் நிலை.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Short Answer','Medium',2,'மெய்நிகர் நினைவகம் என்றால் என்ன? (விரிவாக்கக் கேள்வி 30)','','','','','முதன்மை நினைவகம் குறைவாக இருக்கும் போது வட்டு இடத்தைப் பயன்படுத்தி பெரிய நினைவக இடம் இருப்பது போல செயல்படும் நுட்பம்.','பதிலில் வரையறை மற்றும் முக்கிய செயல்பாடு குறிப்பிடப்பட்டுள்ளது.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'செயல்முறை மேலாண்மையை விரிவாக விளக்குக.','','','','','செயல்முறை உருவாக்கம், நிலைகள், திட்டமிடல், சூழல் மாற்றம், நிறுத்தம் மற்றும் செயல்முறைகளுக்கிடையிலான தொடர்பு ஆகியவை செயல்முறை மேலாண்மையின் பகுதிகள்.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'CPU திட்டமிடல் முறைகளை விளக்குக.','','','','','FCFS, SJF, Priority மற்றும் Round Robin போன்ற முறைகள் CPU நேரத்தை செயல்முறைகளுக்கு ஒதுக்குகின்றன. காத்திருப்பு நேரம், திருப்புமுறை நேரம் மற்றும் பதிலளிப்பு நேரம் போன்ற அளவுகள் மூலம் அவற்றை மதிப்பிடலாம்.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'டெட்லாக் ஏற்படும் நான்கு நிபந்தனைகளை விளக்குக.','','','','','பரஸ்பர விலக்கு, வளத்தை பிடித்துக்கொண்டு காத்திருத்தல், வலுக்கட்டாய பறிமுதல் இல்லாமை மற்றும் சுழற்சி காத்திருத்தல் ஆகியவை ஒரே நேரத்தில் இருந்தால் டெட்லாக் ஏற்படலாம்.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'மெய்நிகர் நினைவகத்தை விளக்குக.','','','','','முதன்மை நினைவகத்தை விட பெரிய நிரல்களை இயக்க வட்டு இடத்தை துணை நினைவகமாகப் பயன்படுத்தும் நுட்பமே மெய்நிகர் நினைவகம். பக்கமிடுதல் போன்ற முறைகள் இதில் பயன்படுகின்றன.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'கோப்பு முறைமையின் செயல்பாடுகளை விளக்குக.','','','','','கோப்பு உருவாக்கம், நீக்கம், வாசிப்பு, எழுதுதல், பெயரிடல், அடைவு மேலாண்மை மற்றும் அணுகல் கட்டுப்பாடு போன்ற சேவைகளை கோப்பு முறைமை வழங்குகிறது.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
INSERT INTO tam_operating_systems_question_bank (subject,language,question_type,difficulty,marks,question,option_a,option_b,option_c,option_d,correct_answer,explanation) VALUES ('TAM - Operating Systems','தமிழ்','Long Answer','Hard',5,'செயல்முறை மேலாண்மையை விரிவாக விளக்குக. (பயன்பாட்டு நிலை 6)','','','','','செயல்முறை உருவாக்கம், நிலைகள், திட்டமிடல், சூழல் மாற்றம், நிறுத்தம் மற்றும் செயல்முறைகளுக்கிடையிலான தொடர்பு ஆகியவை செயல்முறை மேலாண்மையின் பகுதிகள்.','விரிவான பதிலில் வரையறை, செயல்முறை மற்றும் முக்கிய அம்சங்கள் இடம்பெற வேண்டும்.');
